import{_ as t}from"./chunks/ice_actuator_setup.Cx1yq2aU.js";import{_ as o,o as a,c as n,al as r}from"./chunks/framework.7vp1BMOE.js";const d="/px4_user_guide/assets/ice_control_diagram.CG3rMCj0.svg",i="/px4_user_guide/assets/ice_control_state_machine.g2FDejOb.svg",_=JSON.parse('{"title":"Internal Combustion Engines (ICE)","description":"","frontmatter":{},"headers":[],"relativePath":"en/actuators/internal_combustion_engine.md","filePath":"en/actuators/internal_combustion_engine.md"}'),s={name:"en/actuators/internal_combustion_engine.md"};function c(h,e,l,u,p,g){return a(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="internal-combustion-engines-ice" tabindex="-1">Internal Combustion Engines (ICE) <a class="header-anchor" href="#internal-combustion-engines-ice" aria-label="Permalink to &quot;Internal Combustion Engines (ICE)&quot;">​</a></h1><p>PX4 can operate a single spark-ignition internal combustion engine (ICE) — a petrol/nitro two- or four-stroke engine — as the propulsion system of a fixed-wing, VTOL, or helicopter vehicle.</p><p>Unlike an electric motor, an engine cannot simply be commanded to a thrust value: it has to be <em>started</em> (choke, ignition, electric starter), it can <em>die</em> in flight and need restarting, and it must be kept above a minimum idle speed to keep running at all. The <a href="./../modules/modules_system#internal-combustion-engine-control"><code>internal_combustion_engine_control</code></a> module implements this logic as a state machine that drives four dedicated actuator outputs and closes the loop on a measured engine speed (RPM).</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A running combustion engine with a propeller attached is dangerous. The engine can be commanded to start automatically (for example on arming, or on a VTOL transition to fixed-wing), and the starter motor will crank the propeller without further warning.</p><ul><li>Always do your first bench tests with the propeller removed.</li><li>For continuous operation without a propeller, a flywheel is recommended.</li><li>Keep clear of the propeller arc whenever the vehicle is powered.</li><li>Verify that the engine stop functionality (ignition off, choke closed) reliably stops the engine before you rely on it.</li></ul></div><h2 id="hardware-requirements" tabindex="-1">Hardware Requirements <a class="header-anchor" href="#hardware-requirements" aria-label="Permalink to &quot;Hardware Requirements&quot;">​</a></h2><ul><li><p><strong>Throttle servo</strong> connected to a PWM/AUX output.</p></li><li><p><strong>Ignition cut</strong> on an output, typically through a relay or opto-isolated switch that shorts or interrupts the ignition circuit. Optional.</p></li><li><p><strong>Choke servo</strong> on an output (optional if the engine has no choke, or an automatic one — set <a href="./../advanced_config/parameter_reference#ICE_CHOKE_ST_DUR">ICE_CHOKE_ST_DUR</a> to <code>0</code> and leave the function unassigned).</p></li><li><p><strong>Electric starter</strong> on an output, typically through a relay or an ESC driving the starter motor. Optionally, the engine can also be hand-started.</p></li><li><p><strong>RPM sensor</strong> feeding the <code>RPM Input</code> function on a timer-capture-capable PWM pin, for example a Hall-effect or optical sensor on the crankshaft, or an ignition-pulse pickup.</p><p>Many engines have a built-in spark-timing sensor that can be used for this. If yours does not, see <a href="./../sensor/tachometers">Tachometers</a> for other options.</p></li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>RPM feedback is <strong>required</strong>. The state machine only leaves <code>Starting</code> for <code>Running</code> once it sees a measured engine speed above <a href="./../advanced_config/parameter_reference#ICE_MIN_RUN_RPM">ICE_MIN_RUN_RPM</a>. Without a working RPM sensor the module will exhaust its start attempts and latch into the <code>Fault</code> state.</p></div><h2 id="firmware-configuration" tabindex="-1">Firmware Configuration <a class="header-anchor" href="#firmware-configuration" aria-label="Permalink to &quot;Firmware Configuration&quot;">​</a></h2><p>The module and the RPM capture driver are not in the default builds. Add them to the <a href="./../hardware/porting_guide_config">board configuration</a> for your flight controller:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CONFIG_MODULES_INTERNAL_COMBUSTION_ENGINE_CONTROL=y</span></span>
<span class="line"><span>CONFIG_DRIVERS_RPM_CAPTURE=y</span></span></code></pre></div><p>Both can also be enabled interactively with <code>make &lt;target&gt; boardconfig</code>, under <strong>modules</strong> and <strong>drivers</strong> respectively.</p><h2 id="parameter-setup" tabindex="-1">Parameter Setup <a class="header-anchor" href="#parameter-setup" aria-label="Permalink to &quot;Parameter Setup&quot;">​</a></h2><p>Set the following and reboot:</p><ul><li><a href="./../advanced_config/parameter_reference#ICE_EN">ICE_EN</a> to <code>Enabled</code>. The startup script only starts the module if this is set.</li><li><a href="./../advanced_config/parameter_reference#RPM_CAP_ENABLE">RPM_CAP_ENABLE</a> to <code>Enabled</code>.</li><li><a href="./../advanced_config/parameter_reference#RPM_PULS_PER_REV">RPM_PULS_PER_REV</a> to the number of sensor pulses per crankshaft revolution (for example <code>2</code> for a two-magnet setup, or <code>1</code> for a single ignition pulse per revolution on a two-stroke).</li></ul><p>Then work through the remaining <code>ICE_*</code> parameters:</p><ul><li><a href="#actuator-configuration">Actuator Configuration</a> — wire up the engine outputs.</li><li><a href="#start-stop-command-source">Start/Stop Command Source</a> — choose what commands the engine on and off.</li><li><a href="#idle-rpm-governor">Idle RPM Governor</a> — set up and tune closed-loop idle, and the <code>ICE_IDLE_*</code> parameters.</li><li><a href="#parameter-reference">Parameter Reference</a> — the full list, including the start sequence timing.</li></ul><h2 id="actuator-configuration" tabindex="-1">Actuator Configuration <a class="header-anchor" href="#actuator-configuration" aria-label="Permalink to &quot;Actuator Configuration&quot;">​</a></h2><p>Assign the four engine functions and the RPM input in <a href="./../config/actuators">Actuator Configuration</a>, for example:</p><p><img src="`+t+`" alt="Actuator setup for ICE, with the engine output functions and the RPM input highlighted"></p><p>Each setpoint is in the range <code>[0, 1]</code> and is mapped to the <code>[-1, 1]</code> servo range before being scaled to the output&#39;s <strong>Minimum</strong>/<strong>Maximum</strong> values. In other words, a setpoint of <code>0</code> produces the configured <strong>Minimum</strong> output and <code>1</code> produces the configured <strong>Maximum</strong> output (or the reverse, if <strong>Rev Range</strong> is ticked).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>When the engine is commanded off, the throttle setpoint is <code>NAN</code>, which by definition drives the output to its configured <strong>Disarmed</strong> value rather than to <strong>Minimum</strong>. This lets you park the throttle servo at an idle-stop position that is different from the closed-throttle position used to switch off the engine.</p><p>The throttle output also goes to <em>Disarmed</em> while the engine is running if the <a href="#idle-rpm-governor">idle governor</a> is disabled and the throttle demand drops to near zero (the fixed-wing controller stops the motor below 2% thrust).</p></div><p>Points to note when setting the values:</p><ul><li><code>IC Engine Throttle</code> uses <strong>Minimum</strong> for closed throttle and <strong>Maximum</strong> for full throttle. Setting <strong>Disarmed</strong> to a value other than <strong>Minimum</strong> parks the servo at an idle stop when the engine is off, rather than at closed throttle.</li><li><code>IC Engine Choke</code> uses <strong>Minimum</strong> for choke open and <strong>Maximum</strong> for choke closed; tick <strong>Rev Range</strong> if the servo linkage is inverted.</li><li><code>IC Engine Ignition</code> and <code>IC Engine Starter</code> behave as on/off outputs: <strong>Minimum</strong> is &quot;off&quot; and <strong>Maximum</strong> is &quot;on&quot;. Set both values so that the relay switches reliably, and make sure <strong>Disarmed</strong> corresponds to ignition off and starter off.</li><li><code>RPM Input</code> must be on a channel that supports timer capture on your board.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>In the example above the <strong>Actuators</strong> tab stays red in the sidebar, and the page shows &quot;One or more actuator still needs to be assigned to an output&quot;. This is expected for an engine setup and does not stop the engine from running: the airframe&#39;s <code>Motor 1</code> slot is deliberately left unassigned, because the throttle reaches the servo through <code>IC Engine Throttle</code> instead — see <a href="#how-it-works">How It Works</a>.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>While the vehicle is disarmed, every output — including ignition, choke, and starter — is held at its <strong>Disarmed</strong> value, regardless of what the module commands. The engine can only be commanded when <a href="./../advanced_config/prearm_arm_disarm">armed or prearmed</a>.</p></div><p>Whether prearming happens at all is set by <a href="./../advanced_config/parameter_reference#COM_PREARM_MODE">COM_PREARM_MODE</a>, which matters if you want to start the engine before arming (for example from an AUX switch, see <a href="#start-stop-command-source">Start/Stop Command Source</a>):</p><table tabindex="0"><thead><tr><th><code>COM_PREARM_MODE</code></th><th>Effect on the engine outputs</th></tr></thead><tbody><tr><td><code>Disabled</code> (default)</td><td>Never prearms, so the outputs stay at their <strong>Disarmed</strong> values until the vehicle is armed.</td></tr><tr><td><code>Safety button</code></td><td>Outputs become live once the safety switch is released. Has no effect on boards that have no safety button — prearm then never engages.</td></tr><tr><td><code>Always</code></td><td>Outputs become live 5 s after boot.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>With <code>Always</code> the ignition, choke, and starter outputs are live shortly after power-up, before any arming check has run. The engine can be commanded to crank on a vehicle that was never armed, so treat the propeller as live whenever the vehicle is powered.</p></div><h2 id="start-stop-command-source" tabindex="-1">Start/Stop Command Source <a class="header-anchor" href="#start-stop-command-source" aria-label="Permalink to &quot;Start/Stop Command Source {#start-stop-command-source}&quot;">​</a></h2><p><a href="./../advanced_config/parameter_reference#ICE_ON_SOURCE">ICE_ON_SOURCE</a> selects what asks for the engine to run:</p><table tabindex="0"><thead><tr><th>Value</th><th>Engine is requested on when</th></tr></thead><tbody><tr><td><code>On arming - disarming</code> (0)</td><td>The vehicle is armed. This is the default.</td></tr><tr><td><code>Aux1</code> (1)</td><td>The AUX1 manual control channel is above <code>0.5</code>; requested off when it goes below <code>-0.5</code>. Map a switch to it with <code>RC_MAP_AUX1</code>.</td></tr><tr><td><code>Aux2</code> (2)</td><td>As above, using AUX2 and <code>RC_MAP_AUX2</code>.</td></tr><tr><td><code>On Vtol Transitions</code> (3)</td><td>The vehicle is in fixed-wing mode or transitioning to fixed-wing. Use this on a hybrid VTOL where the engine only drives the pusher/forward propeller.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>For the AUX sources, values between <code>-0.5</code> and <code>0.5</code> leave the request unchanged. This dead zone means a three-position switch has a middle position that does not change the engine state, and it prevents a channel that is momentarily centred (or lost and defaulted to zero) from cutting the engine.</p></div><h2 id="idle-rpm-governor" tabindex="-1">Idle RPM Governor <a class="header-anchor" href="#idle-rpm-governor" aria-label="Permalink to &quot;Idle RPM Governor&quot;">​</a></h2><p>Left at a fixed low throttle, an engine tends either to die or to sit at an unpredictable idle speed that depends on temperature, air density, and mixture. The idle governor closes the loop on measured RPM whenever the throttle demand is low, keeping the engine alive and ready to accelerate.</p><p>It is enabled by setting <a href="./../advanced_config/parameter_reference#ICE_IDLE_RPM">ICE_IDLE_RPM</a> to a non-zero idle speed. When enabled, the <code>Running</code> state has two sub-states, reported in <code>InternalCombustionEngineStatus.substate</code>:</p><ul><li><code>Run</code> — the throttle demand from allocation is passed straight through.</li><li><code>Idle</code> — the throttle output is produced by the governor instead.</li></ul><p>The module enters <code>Idle</code> when the throttle demand drops below 2% (or becomes invalid, i.e. the vehicle is disarmed), <strong>or</strong> whenever the measured RPM falls below the idle setpoint. The second condition is what catches a sagging engine: even at high commanded throttle, if the engine is being dragged below its idle speed the governor takes over and pushes the throttle to recover it. It leaves <code>Idle</code> again as soon as the throttle demand exceeds the governor&#39;s current output, so the handover happens without a step in the output.</p><h3 id="control-structure" tabindex="-1">Control Structure <a class="header-anchor" href="#control-structure" aria-label="Permalink to &quot;Control Structure&quot;">​</a></h3><p>The governor is a feed-forward plus PI controller with output clamped to <code>[0, 1]</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>throttle = ICE_IDLE_THR_FF + P · e + ∫ I · e dt</span></span>
<span class="line"><span>       e = ICE_IDLE_RPM − rpm_estimate</span></span>
<span class="line"><span>       P = ICE_IDLE_RPM_P · 1e-3</span></span>
<span class="line"><span>       I = ICE_IDLE_RPM_I · 1e-3</span></span></code></pre></div><p>The <code>1e-3</code> scaling is what makes the gains convenient to reason about:</p><ul><li><a href="./../advanced_config/parameter_reference#ICE_IDLE_RPM_P">ICE_IDLE_RPM_P</a> is the normalised throttle added per <strong>1000 RPM</strong> of error. <code>ICE_IDLE_RPM_P = 1</code> means an engine running 500 RPM slow gets <code>+0.5</code> throttle.</li><li><a href="./../advanced_config/parameter_reference#ICE_IDLE_RPM_I">ICE_IDLE_RPM_I</a> is the normalised throttle added per <strong>1000 RPM·s</strong> of accumulated error. <code>ICE_IDLE_RPM_I = 1</code> means a steady 100 RPM error winds the output up by <code>0.1</code> every second.</li><li><a href="./../advanced_config/parameter_reference#ICE_IDLE_THR_FF">ICE_IDLE_THR_FF</a> is the throttle that holds the idle speed on its own, so the PI terms only have to correct for the difference. It is applied as a constant offset whenever the governor is active.</li></ul><p>The integrator is limited to <code>±1</code> and uses conditional integration: it stops winding up in whichever direction is already driving the output into saturation. It is reset to zero every time the engine reaches <code>Running</code>, so a start never inherits wind-up from a previous run.</p><h3 id="tuning-procedure" tabindex="-1">Tuning Procedure <a class="header-anchor" href="#tuning-procedure" aria-label="Permalink to &quot;Tuning Procedure&quot;">​</a></h3><p>Do this on the ground, with the propeller removed or the vehicle firmly restrained, and with the engine warm.</p><ol><li><strong>Find the idle speed.</strong> Pick the <a href="./../advanced_config/parameter_reference#ICE_IDLE_RPM">ICE_IDLE_RPM</a> you want — low enough not to produce useful thrust, high enough that the engine runs smoothly and can accelerate without hesitating. The engine&#39;s specification or a hand-throttled test is the starting point.</li><li><strong>Find the feed-forward.</strong> With the governor still off (<code>ICE_IDLE_RPM = 0</code>), start the engine and hold it at that RPM with the throttle stick in a manual mode. Read the commanded throttle off the log (<code>internal_combustion_engine_control.throttle_control</code>), set <a href="./../advanced_config/parameter_reference#ICE_IDLE_THR_FF">ICE_IDLE_THR_FF</a> to it, and set <code>ICE_IDLE_RPM</code> to the target.</li><li><strong>Verify feed-forward only.</strong> With both gains still at <code>0</code>, restart and let the engine idle. It should settle near the setpoint. A large steady offset means the feed-forward is wrong — correct it before adding gains, because the PI terms are only meant to trim.</li><li><strong>Add proportional gain.</strong> Raise <a href="./../advanced_config/parameter_reference#ICE_IDLE_RPM_P">ICE_IDLE_RPM_P</a> in steps (<code>0.2</code> is a reasonable first step) until the engine recovers briskly when you disturb it — for example by briefly blipping the throttle up and releasing it. Back off as soon as you see the RPM hunting or the throttle oscillating.</li><li><strong>Add integral gain.</strong> Raise <a href="./../advanced_config/parameter_reference#ICE_IDLE_RPM_I">ICE_IDLE_RPM_I</a> just enough to remove any remaining steady-state RPM offset within a few seconds. Too much integral shows up as a slow oscillation around the setpoint.</li><li><strong>Check the handover.</strong> Sweep the throttle demand up and back down through the idle point and confirm there is no jump or dead spot as the sub-state switches between <code>Idle</code> and <code>Run</code>.</li></ol><p>The signals to look at in the <a href="./../log/flight_log_analysis">flight log</a>:</p><table tabindex="0"><thead><tr><th>Signal</th><th>Use</th></tr></thead><tbody><tr><td><code>rpm.rpm_estimate</code></td><td>Measured engine speed — compare against <code>ICE_IDLE_RPM</code>.</td></tr><tr><td><code>internal_combustion_engine_control.throttle_control</code></td><td>Throttle actually commanded, after the governor and the slew rate limit.</td></tr><tr><td><code>internal_combustion_engine_status.substate</code></td><td>Whether the governor is active (<code>1</code> = <code>Idle</code>).</td></tr><tr><td><code>internal_combustion_engine_status.pid_idle_rpm_integral</code></td><td>Integrator state. Parked at <code>±1</code> means it is saturated and the feed-forward is far off.</td></tr><tr><td><code>internal_combustion_engine_status.state</code></td><td>State machine state — reveals unnoticed restarts.</td></tr></tbody></table><p>Both <code>internal_combustion_engine_*</code> topics are logged when the module is running.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><code>rpm_capture</code> low-pass filters the RPM estimate with a 0.5 s time constant. That lag is part of the loop you are tuning and puts a practical ceiling on how high the gains can go before the governor starts hunting.</p></div><h2 id="parameter-reference" tabindex="-1">Parameter Reference <a class="header-anchor" href="#parameter-reference" aria-label="Permalink to &quot;Parameter Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Unit</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><a href="./../advanced_config/parameter_reference#ICE_EN">ICE_EN</a></td><td>—</td><td><code>0</code></td><td>Start the ICE control module. Requires a reboot.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#ICE_ON_SOURCE">ICE_ON_SOURCE</a></td><td>—</td><td><code>0</code></td><td>What requests the engine on/off: arming, AUX1, AUX2, or VTOL transitions.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#ICE_MIN_RUN_RPM">ICE_MIN_RUN_RPM</a></td><td>rpm</td><td><code>2000</code></td><td>RPM above which the engine counts as running.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#ICE_IGN_DELAY">ICE_IGN_DELAY</a></td><td>s</td><td><code>0</code></td><td>Delay between switching on the ignition and engaging the starter.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#ICE_CHOKE_ST_DUR">ICE_CHOKE_ST_DUR</a></td><td>s</td><td><code>5</code></td><td>How long the choke stays closed on the first start attempt.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#ICE_STRT_DUR">ICE_STRT_DUR</a></td><td>s</td><td><code>5</code></td><td>Cranking time per attempt after the choke opens, before declaring a timeout.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#ICE_STRT_THR">ICE_STRT_THR</a></td><td>norm</td><td><code>0.1</code></td><td>Throttle held during choking and cranking.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#ICE_STRT_ATTEMPT">ICE_STRT_ATTEMPT</a></td><td>—</td><td><code>3</code></td><td>Start attempts before entering <code>Fault</code>. <code>0</code> means a single attempt.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#ICE_RUN_FAULT_D">ICE_RUN_FAULT_D</a></td><td>—</td><td><code>1</code></td><td>Detect an engine stop while running and attempt a restart.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#ICE_STOP_CHOKE">ICE_STOP_CHOKE</a></td><td>—</td><td><code>1</code></td><td>Close the choke while the engine is stopped or in fault.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#ICE_THR_SLEW">ICE_THR_SLEW</a></td><td>1/s</td><td><code>0.5</code></td><td>Maximum rate of change of the throttle output.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#ICE_IDLE_RPM">ICE_IDLE_RPM</a></td><td>rpm</td><td><code>0</code></td><td>Idle RPM setpoint. <code>0</code> disables the idle governor.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#ICE_IDLE_THR_FF">ICE_IDLE_THR_FF</a></td><td>norm</td><td><code>0</code></td><td>Feed-forward throttle for the idle governor.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#ICE_IDLE_RPM_P">ICE_IDLE_RPM_P</a></td><td>—</td><td><code>0</code></td><td>Idle governor proportional gain, per 1000 RPM of error.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#ICE_IDLE_RPM_I">ICE_IDLE_RPM_I</a></td><td>—</td><td><code>0</code></td><td>Idle governor integral gain, per 1000 RPM·s of error.</td></tr></tbody></table><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th></tr></thead><tbody><tr><td>Nothing happens at all; <code>internal_combustion_engine_control status</code> reports the module is not running</td><td><code>ICE_EN</code> is not set, or the module is not in the firmware. Check the <a href="#firmware-configuration">build configuration</a> and reboot.</td></tr><tr><td>The engine runs but the state machine goes to <a href="#state-machine"><code>Fault</code></a></td><td>The RPM sensor is not working or is misconfigured. Check <code>RPM_CAP_ENABLE</code>, <code>RPM_PULS_PER_REV</code>, and that the sensor is on a capture-capable pin; compare <code>rpm.rpm_estimate</code> against a hand tachometer.</td></tr><tr><td>Outputs never move even though the state machine advances</td><td>The vehicle is disarmed and not prearmed, so outputs are held at their <strong>Disarmed</strong> values. See the <a href="#actuator-configuration">note above</a> on <code>COM_PREARM_MODE</code>.</td></tr><tr><td>The starter cranks but the engine never fires</td><td>There may be no fuel in the engine yet. Closing the choke is what draws fuel in, so a dry engine needs a longer priming window — increase <code>ICE_CHOKE_ST_DUR</code>. Also check the cranking time (<code>ICE_STRT_DUR</code>) and the start throttle (<code>ICE_STRT_THR</code>), and note that too much choke floods the engine.</td></tr><tr><td>The engine fires and then dies just after <code>Starting</code> finishes</td><td>No idle governor. Set up the <a href="#idle-rpm-governor">idle governor</a>; with <code>ICE_IDLE_RPM = 0</code> there is nothing holding the engine up when the throttle demand is zero.</td></tr><tr><td>Repeated in-air restarts logged as <code>IC engine fault detected</code></td><td><code>ICE_MIN_RUN_RPM</code> is set too close to the actual idle speed, so normal idle dips read as an engine stop. Raise the idle setpoint or lower the threshold.</td></tr><tr><td>The engine bogs down or stalls on throttle up</td><td><code>ICE_THR_SLEW</code> is too high for the engine. Reduce it so the throttle opens more gradually.</td></tr></tbody></table><h2 id="developer-information" tabindex="-1">Developer Information <a class="header-anchor" href="#developer-information" aria-label="Permalink to &quot;Developer Information&quot;">​</a></h2><h3 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h3><img src="`+d+'" alt="ICE control architecture" class="diagram-invert"><p>The module sits between the <a href="./../config/actuators">control allocator</a> and the outputs:</p><ul><li>It takes the <strong>throttle demand</strong> from <code>actuator_motors.control[0]</code>, i.e. the thrust that allocation computed for <code>Motor 1</code>.<div class="info custom-block"><p class="custom-block-title">INFO</p><p>The engine takes its throttle from whichever rotor the airframe geometry defines as <code>Motor 1</code> (rotor 0, <code>CA_ROTOR0_*</code>), so you must set up the geometry with the engine as rotor 0. On a standard VTOL, this means making the pusher rotor 0 rather than the last rotor. You do not need to (and should not) assign an output for the <code>Motor 1</code> function.</p></div></li><li>It takes the <strong>on/off request</strong> from <a href="./../msg_docs/VehicleStatus">VehicleStatus</a> (arming state, or the VTOL transition) or from <a href="./../msg_docs/ManualControlSetpoint">ManualControlSetpoint</a> (the AUX channels), depending on <a href="#start-stop-command-source">ICE_ON_SOURCE</a>.</li><li>It runs the start/stop state machine and publishes <a href="./../msg_docs/InternalCombustionEngineControl">InternalCombustionEngineControl</a> with the setpoints for ignition, throttle, choke, and starter.</li><li>The mixer maps those four fields to the four <code>IC Engine *</code> <a href="./../config/actuators">output functions</a>, which is where you wire the engine hardware.</li><li>It subscribes to <a href="./../msg_docs/Rpm">Rpm</a> to know whether the engine is actually turning, and publishes <a href="./../msg_docs/InternalCombustionEngineStatus">InternalCombustionEngineStatus</a> with the current state.</li></ul><p>The module runs at 50 Hz.</p><h4 id="output-functions" tabindex="-1">Output Functions <a class="header-anchor" href="#output-functions" aria-label="Permalink to &quot;Output Functions&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Output function</th><th>Field in <code>InternalCombustionEngineControl</code></th><th>Meaning</th></tr></thead><tbody><tr><td><code>IC Engine Ignition</code></td><td><code>ignition_on</code></td><td>Spark/ignition enable. <code>false</code> cuts the spark and stops the engine (optional: many engine spark boxes always run when powered).</td></tr><tr><td><code>IC Engine Throttle</code></td><td><code>throttle_control</code></td><td>Throttle servo setpoint, <code>0</code>…<code>1</code>. <code>NAN</code> while the engine is commanded off.</td></tr><tr><td><code>IC Engine Choke</code></td><td><code>choke_control</code></td><td>Choke servo setpoint, <code>0</code>…<code>1</code>, where <code>1</code> is fully closed (richest mixture). Optional actuator.</td></tr><tr><td><code>IC Engine Starter</code></td><td><code>starter_engine_control</code></td><td>Electric starter motor setpoint, <code>0</code>…<code>1</code>. Optional actuator: the engine can also be hand-started.</td></tr></tbody></table><h3 id="state-machine" tabindex="-1">State Machine <a class="header-anchor" href="#state-machine" aria-label="Permalink to &quot;State Machine&quot;">​</a></h3><img src="'+i+'" alt="ICE control state machine" class="diagram-invert"><p>The module has four states, reported in <code>InternalCombustionEngineStatus.state</code>:</p><table tabindex="0"><thead><tr><th>State</th><th>Ignition</th><th>Throttle</th><th>Choke</th><th>Starter</th></tr></thead><tbody><tr><td><code>Stopped</code></td><td>off</td><td><code>NAN</code> (→ <strong>Disarmed</strong> value)</td><td><code>ICE_STOP_CHOKE ? 1 : 0</code></td><td><code>0</code></td></tr><tr><td><code>Starting</code></td><td>on</td><td><code>ICE_STRT_THR</code></td><td>see <a href="#start-sequence">start sequence</a></td><td>see <a href="#start-sequence">start sequence</a></td></tr><tr><td><code>Running</code></td><td>on</td><td>motor 1 demand, or idle governor output</td><td><code>0</code></td><td><code>0</code></td></tr><tr><td><code>Fault</code></td><td>off</td><td><code>0</code></td><td><code>ICE_STOP_CHOKE ? 1 : 0</code></td><td><code>0</code></td></tr></tbody></table><p>Transitions:</p><ul><li><code>Stopped</code> → <code>Starting</code> when the engine is requested on and the start attempt budget is not exhausted.</li><li><code>Starting</code> → <code>Running</code> as soon as the measured RPM exceeds <a href="./../advanced_config/parameter_reference#ICE_MIN_RUN_RPM">ICE_MIN_RUN_RPM</a>. This can happen part way through an attempt.</li><li><code>Starting</code> → <code>Fault</code> when all attempts have been used without the engine coming up.</li><li><code>Running</code> → <code>Starting</code> if the RPM drops back below the threshold and <a href="./../advanced_config/parameter_reference#ICE_RUN_FAULT_D">ICE_RUN_FAULT_D</a> is enabled — this is the automatic in-air restart. An <code>IC engine fault detected</code> event is emitted.</li><li>Any state → <code>Stopped</code> when the engine is requested off. This also resets the attempt counter, so switching the request off and on again is the way to clear a <code>Fault</code>.</li></ul><p>Both <code>Starting</code> and <code>Running</code> have sub-states, reported in <code>InternalCombustionEngineStatus.substate</code>. <code>Starting</code> alternates between cranking and a one-second rest between attempts (see <a href="#start-sequence">Start Sequence</a>), and <code>Running</code> switches between passing the throttle demand straight through and running the <a href="#idle-rpm-governor">idle governor</a>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The throttle setpoint is rate limited by <a href="./../advanced_config/parameter_reference#ICE_THR_SLEW">ICE_THR_SLEW</a> in all states, which protects the engine from abrupt throttle steps that would make it bog down or stall. The limit does not apply to the <code>NAN</code> used in <code>Stopped</code>; the slew state is reset to zero instead, so the next start ramps up from closed throttle.</p></div><h4 id="start-sequence" tabindex="-1">Start Sequence <a class="header-anchor" href="#start-sequence" aria-label="Permalink to &quot;Start Sequence&quot;">​</a></h4><p>One start attempt runs the following timeline, measured from entry into the attempt:</p><table tabindex="0"><thead><tr><th>From</th><th>To</th><th>Ignition</th><th>Choke</th><th>Starter</th><th>Throttle</th></tr></thead><tbody><tr><td><code>0</code></td><td><code>ICE_IGN_DELAY</code></td><td>on</td><td><code>1</code></td><td><code>0</code></td><td><code>ICE_STRT_THR</code></td></tr><tr><td><code>ICE_IGN_DELAY</code></td><td><code>ICE_IGN_DELAY + ICE_CHOKE_ST_DUR</code></td><td>on</td><td><code>1</code></td><td><code>1</code></td><td><code>ICE_STRT_THR</code></td></tr><tr><td><code>ICE_IGN_DELAY + ICE_CHOKE_ST_DUR</code></td><td><code>ICE_IGN_DELAY + ICE_CHOKE_ST_DUR + ICE_STRT_DUR</code></td><td>on</td><td><code>0</code></td><td><code>1</code></td><td><code>ICE_STRT_THR</code></td></tr></tbody></table><ul><li><a href="./../advanced_config/parameter_reference#ICE_IGN_DELAY">ICE_IGN_DELAY</a> holds the starter off for a moment after the ignition is switched on, for ignition systems that need time to come up.</li><li><a href="./../advanced_config/parameter_reference#ICE_CHOKE_ST_DUR">ICE_CHOKE_ST_DUR</a> is how long the choke stays closed. Note that the starter is already cranking during this window.</li><li><a href="./../advanced_config/parameter_reference#ICE_STRT_DUR">ICE_STRT_DUR</a> is how much longer the starter cranks with the choke open before the attempt is declared timed out.</li></ul><p>If the attempt times out, the module rests for <strong>1 second</strong> with the ignition off and the throttle at its disarmed value (to reduce starter motor wear) and then begins the next attempt.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Choke and ignition delay are applied on the <strong>first</strong> attempt only. Retries crank with the choke open immediately, on the assumption that the first attempt already primed the engine and that further choking would flood it.</p></div><p><a href="./../advanced_config/parameter_reference#ICE_STRT_ATTEMPT">ICE_STRT_ATTEMPT</a> caps the number of attempts before the module gives up and enters <code>Fault</code>. A value of <code>0</code> means a single attempt with no retry.</p><h3 id="status-and-telemetry" tabindex="-1">Status and Telemetry <a class="header-anchor" href="#status-and-telemetry" aria-label="Permalink to &quot;Status and Telemetry&quot;">​</a></h3><ul><li><a href="./../msg_docs/InternalCombustionEngineControl">InternalCombustionEngineControl</a> carries the commanded setpoints and the current user request.</li><li><a href="./../msg_docs/InternalCombustionEngineStatus">InternalCombustionEngineStatus</a> carries the state machine state and the governor&#39;s integrator. The same topic is used by the <a href="./../dronecan/">DroneCAN</a> ICE bridge (<code>UAVCAN_SUB_ICE</code>), which fills in the richer engine telemetry — temperatures, pressures, fuel flow — reported by a smart ECU.</li><li>The status topic is streamed to a ground station as the MAVLink <a href="https://mavlink.io/en/messages/common.html#EFI_STATUS" target="_blank" rel="noreferrer">EFI_STATUS</a> message.</li></ul><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./../modules/modules_system#internal-combustion-engine-control"><code>internal_combustion_engine_control</code></a> — module command line reference.</li><li><a href="./../config/actuators">Actuator Configuration</a> — assigning output functions.</li><li><a href="./../dronecan/">DroneCAN Peripherals</a> — for engines with a smart ECU reporting over DroneCAN.</li></ul>',81)])])}const b=o(s,[["render",c]]);export{_ as __pageData,b as default};
